-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.prune_quizzes(keep jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  removed integer;
begin
  -- A missing list would mean «keep nothing»: refuse it instead of emptying the table (as prune_anki).
  if jsonb_typeof(keep) is distinct from 'array' then
    raise exception 'prune_quizzes: keep needs the array of the ids of the published tests';
  end if;
  delete from public.quizzes
   where id not in (select jsonb_array_elements_text(keep));
  get diagnostics removed = row_count;
  return removed;
end;
$function$;

grant execute on function public.prune_quizzes(keep jsonb) to service_role;
